package pipeline

import "sync"

// FanIn runs fn over every input concurrently and returns the results in the
// same order as the inputs.
func FanIn(inputs []int, workers int, fn func(int) int) []int {
	out := make([]int, len(inputs))
	jobs := make(chan int)
	var wg sync.WaitGroup

	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range jobs {
				out[i] = fn(inputs[i])
			}
		}()
	}

	for i := range inputs {
		jobs <- i
	}
	close(jobs)
	wg.Wait()
	return out
}

package cache

import "container/list"

// entry stores a key and its associated value.
type entry struct {
	key   string
	value int
}

// LRU is a fixed-capacity least-recently-used cache.
type LRU struct {
	capacity int
	items    map[string]*list.Element
	order    *list.List // front = most recently used, back = least recently used
}

// NewLRU creates a new LRU cache with the given capacity.
func NewLRU(capacity int) *LRU {
	if capacity <= 0 {
		capacity = 1
	}
	return &LRU{
		capacity: capacity,
		items:    make(map[string]*list.Element),
		order:    list.New(),
	}
}

// Get retrieves a value by key, marking it as most recently used.
// The second return value reports whether the key was found.
func (c *LRU) Get(key string) (int, bool) {
	el, ok := c.items[key]
	if !ok {
		return 0, false
	}
	c.order.MoveToFront(el)
	return el.Value.(*entry).value, true
}

// Put inserts or updates a key/value pair.
// On an existing key it updates the value without growing the cache.
// When the cache is full it evicts the least recently used entry.
func (c *LRU) Put(key string, value int) {
	el, ok := c.items[key]
	if ok {
		el.Value.(*entry).value = value
		c.order.MoveToFront(el)
		return
	}

	// Evict the least recently used entry if at capacity.
	if c.order.Len() >= c.capacity {
		oldest := c.order.Back()
		if oldest != nil {
			c.order.Remove(oldest)
			delete(c.items, oldest.Value.(*entry).key)
		}
	}

	ent := &entry{key: key, value: value}
	c.order.PushFront(ent)
	c.items[key] = c.order.Front()
}

// Len returns the number of entries currently stored in the cache.
func (c *LRU) Len() int {
	return c.order.Len()
}

