using System;

public class TelemetrySender
{
    private const int OpcodeMaxLength = 8;

    private readonly NetworkManager _network;

    public TelemetrySender(NetworkManager network)
    {
        _network = network ?? throw new ArgumentNullException(nameof(network));
    }

    public void Send(string opcode, string payload)
    {
        if (opcode == null)
        {
            throw new ArgumentNullException(nameof(opcode));
        }

        var truncatedOpcode = opcode.Length > OpcodeMaxLength
            ? opcode.Substring(0, OpcodeMaxLength)
            : opcode;

        string frame = _network.Encode(truncatedOpcode, payload);
        _network.Enqueue(frame);
    }
}

